func TestMCPTunnelCreateDoesNotRetryAmbiguousFailure(t *testing.T) {
	var requests atomic.Int64
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		requests.Add(1)
		if req.Method != http.MethodPost || req.URL.Path != "/v1/tunnels" {
			t.Errorf("unexpected request: %s %s", req.Method, req.URL.Path)
		}
		// An upstream error can occur after allocation. Retrying would create an
		// additional tunnel because this API has no idempotency key contract.
		writeTunnelError(w, http.StatusInternalServerError, "Synthetic upstream failure")
	}))
	t.Cleanup(server.Close)
	managed, state := tunnelResourceAndState(t, server.URL)
	plan := tfsdk.Plan{Schema: state.Schema}
	model := tunnelTestModel{
		ID: types.StringUnknown(), Name: types.StringValue("new tunnel"),
		Description: types.StringValue(""), Creator: types.StringUnknown(),
		TenantIDs: types.ListUnknown(types.StringType), WorkspaceIDs: types.ListUnknown(types.StringType),
		OrganizationIDs: types.ListUnknown(types.StringType),
	}
	if diagnostics := plan.Set(context.Background(), &model); diagnostics.HasError() {
		t.Fatalf("initialize tunnel plan: %v", diagnostics)
	}
	response := &frameworkresource.CreateResponse{State: tfsdk.State{Schema: state.Schema}}
	managed.Create(context.Background(), frameworkresource.CreateRequest{Plan: plan}, response)
	if !response.Diagnostics.HasError() {
		t.Fatal("ambiguous create failure must be reported")
	}
	if got := requests.Load(); got != 1 {
		t.Fatalf("non-idempotent create was attempted %d times, want exactly once", got)
	}
}

