func TestMCPTunnelSchemaContainsOnlyMetadata(t *testing.T) {
	managed := newTunnelResource(t)
	var response frameworkresource.SchemaResponse
	managed.Schema(context.Background(), frameworkresource.SchemaRequest{}, &response)
	var names []string
	for name, attribute := range response.Schema.Attributes {
		names = append(names, name)
		if name != "name" && name != "description" && (!attribute.IsComputed() || attribute.IsOptional() || attribute.IsRequired()) {
			t.Errorf("attribute %q must be computed only", name)
		}
	}
	sort.Strings(names)
	want := []string{"creator", "description", "id", "name", "organization_ids", "tenant_ids", "workspace_ids"}
	if !reflect.DeepEqual(names, want) {
		t.Fatalf("tunnel schema must contain only metadata, got %v", names)
	}
}

